#!/usr/bin/env python3
"""
apply-changes.py

Deterministic change-applier for the proofread pipeline (src/skills/proofread/
SKILL.md Step 5, as code). Reads a changes-schema.json payload
(src/skills/proofread/references/changes-schema.json) plus the text file the
changes were found against (PROOF_BASE), applies every eligible change to
that file, and emits the full annotated change list on stdout as JSON so
nothing is silently discarded -- every change comes back either
`applied: true` or `applied: false` with a `skipReason` from the schema's
documented set (no-match | ambiguous-match | overlap | citation-guard |
meaning-risk | comment-only | refuted). This script only ever produces
no-match, ambiguous-match, overlap, meaning-risk and comment-only; the
citation-guard and refuted reasons are set by upstream stages
(citation-guard.py and the refute-verify workflow stage respectively) and are
passed through unchanged if already present on an incoming change.

Eligibility (schema `meaningRisk` / `after` contract):
  - Only changes with meaningRisk == "low" AND a non-null `after` are ever
    applied.
  - meaningRisk == "medium" or "high" -> applied=false, skipReason=
    "meaning-risk" (never attempted, regardless of match quality).
  - after is null -> applied=false, skipReason="comment-only" (this is a
    genuine schema state: editorial changes and any change that is a
    flag/comment rather than an edit).

Recorded gotchas this script exists to honour (plan of record, Phase 0
RESULT and Research digest Q4):
  - NFC-normalize both the source text and every `before`/`after` before
    matching -- substring matching on raw Hebrew text is fragile under NFC/
    NFD normalization drift.
  - Apply strictly bottom-to-top by line so an edit never shifts the offsets
    of a change below it in the same run.
  - Locate each change by a CONTEXT-ANCHORED fallback chain -- exact line
    match, then trimmed-line-ending match, then whitespace-trimmed match --
    NEVER by raw line number alone. The residual pass runs on already-
    corrected text where every line below a prior applied edit has shifted,
    so a raw line-number lookup would silently apply to the wrong line.
  - Merge overlapping same-span edits (same resolved line + overlapping
    `before` span) into a single application; a change swallowed by that
    merge is recorded skipReason="overlap", never dropped.
  - Require a UNIQUE match for `before` within its resolved line. If more
    than one occurrence of `before` appears on the recorded line (under any
    of the three fallback views), that is unconditionally reported as
    skipReason="ambiguous-match". This script never widens the search to
    neighbouring lines to try to resolve that ambiguity -- doing so would
    mean guessing which line the change actually targets, which is exactly
    the kind of whole-file/wrong-line guessing this script exists to avoid.
    (Line-number drift -- the recorded line no longer containing `before`
    at all -- is a separate case, handled below by skipReason="no-match";
    it never triggers a search on other lines either.)
  - NEVER fall back to a whole-file replacement under any circumstance.
    Every application is scoped to exactly one resolved line.

Usage:
    python3 apply-changes.py --changes changes.json --proof-base article.md \
        [--output out.md] [--dry-run] [--json]

--changes     Path to a JSON file matching changes-schema.json: either the
              full object ({"stage": ..., "changes": [...]}) or a bare JSON
              array of change objects.
--proof-base  Path to the PROOF_BASE text file the changes reference and
              (unless --dry-run) the file that gets rewritten in place, or
              written to --output if given.
--output      Optional path to write the modified text to, instead of
              overwriting --proof-base in place. Ignored under --dry-run.
--dry-run     Report what would happen (the full annotated changes payload)
              without writing anything -- neither --proof-base nor --output
              is touched.
--json        Emit JSON (currently the only supported output format, kept
              explicit like sibling scripts in this directory).

Always prints the full annotated changes payload (same shape as the input)
to stdout as JSON and exits 0, unless the input files cannot be read/parsed
(exit 2, usage/IO error).

No third-party dependencies -- Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import sys
import unicodedata
from pathlib import Path
from typing import Optional


def _nfc(text: Optional[str]) -> Optional[str]:
    """NFC-normalize, tolerating None (the schema allows `after: null`)."""
    if text is None:
        return None
    return unicodedata.normalize("NFC", text)


def _find_unique_span(line_text: str, needle: str) -> Optional[tuple[int, int]]:
    """Return (start, end) of `needle` in `line_text` if it occurs exactly
    once; None if it does not occur; raises AmbiguousMatch if it occurs more
    than once.
    """
    first = line_text.find(needle)
    if first == -1:
        return None
    second = line_text.find(needle, first + 1)
    if second != -1:
        raise AmbiguousMatch()
    return (first, first + len(needle))


class AmbiguousMatch(Exception):
    """Raised internally when `before` occurs more than once on a resolved line."""


class AnchorAmbiguous(Exception):
    """Raised when equally near source lines contain the anchor."""


def _match_on_line(lines_norm: list[str], idx: int, before_norm: str) -> Optional[tuple[int, int]]:
    """Try the three-step context-anchored chain (exact, trimmed-line-ending,
    whitespace-trimmed) against a single 0-based line index. Returns the
    span within the ORIGINAL (untrimmed) line text, or None if `before_norm`
    does not occur there. Raises AmbiguousMatch if it occurs more than once
    on that line under any of the three views (trimming only removes
    characters at the ends, so a genuine duplicate on the line is ambiguous
    regardless of which view finds it).
    """
    raw_line = lines_norm[idx]
    candidates = [raw_line, raw_line.rstrip(), raw_line.strip()]

    seen_texts = set()
    for candidate in candidates:
        if candidate in seen_texts:
            continue
        seen_texts.add(candidate)
        span = _find_unique_span(candidate, before_norm)
        if span is not None:
            if candidate is raw_line:
                return span
            # candidate is a trimmed view; re-anchor the same occurrence in
            # the untrimmed line (still required to be unique there, since
            # trimming can only remove occurrences at the very ends).
            return _find_unique_span(raw_line, before_norm)
    return None


def _resolve_line(lines_norm: list[str], line_no: int, before_norm: str) -> tuple[Optional[int], Optional[tuple[int, int]]]:
    """Locate `before_norm` on the 1-based `line_no` using the
    context-anchored fallback chain: exact/trimmed-ending/whitespace-trimmed
    match on the recorded line itself. Returns (resolved_line_index0, span)
    or (None, None) if the recorded line does not contain `before_norm`
    under any of the three views (skipReason="no-match" upstream).

    Raises AmbiguousMatch if the recorded line contains more than one
    occurrence of `before_norm`. This is unconditional: the search is never
    widened to neighbouring lines to try to disambiguate or to recover from
    line-number drift. Guessing at a different line is exactly the
    whole-file-fallback failure mode this script exists to avoid, so a
    genuine ambiguity is always reported, never silently resolved.
    """
    if not (1 <= line_no <= len(lines_norm)):
        return None, None

    idx = line_no - 1
    span = _match_on_line(lines_norm, idx, before_norm)
    if span is not None:
        return idx, span
    return None, None


def _spans_overlap(a_start: int, a_end: int, b_start: int, b_end: int) -> bool:
    return a_start < b_end and b_start < a_end


def _find_nth_span(line_text: str, needle: str, occurrence: int) -> Optional[tuple[int, int]]:
    """Return the span of the `occurrence`-th (1-based) occurrence of `needle`
    in `line_text`, counting non-overlapping matches the same way
    `re.finditer`/must-catch.py does (advance past the whole match, not by one
    character). None if the line has fewer than `occurrence` occurrences.
    """
    start = 0
    count = 0
    while True:
        idx = line_text.find(needle, start)
        if idx == -1:
            return None
        count += 1
        if count == occurrence:
            return (idx, idx + len(needle))
        start = idx + len(needle)


def _resolve_line_by_occurrence(
    lines_norm: list[str], line_no: int, before_norm: str, occurrence: int
) -> tuple[Optional[int], Optional[tuple[int, int]]]:
    """Locate the `occurrence`-th instance of `before_norm` on the exact
    1-based `line_no`. Unlike `_resolve_line`, this is never ambiguous by
    construction -- the occurrence index IS the disambiguator -- and it never
    widens the search to neighbouring lines, for the same reason `_resolve_line`
    doesn't: guessing at a different line is the whole-file-fallback failure
    mode this script exists to avoid.
    """
    if not (1 <= line_no <= len(lines_norm)):
        return None, None
    idx = line_no - 1
    span = _find_nth_span(lines_norm[idx], before_norm, occurrence)
    if span is None:
        return None, None
    return idx, span


def apply_changes(payload, proof_base_text: str) -> tuple[dict | list, str]:
    """Apply eligible changes in `payload` to `proof_base_text`.

    Returns (annotated_payload, new_text). `new_text` equals
    `proof_base_text` untouched when no change is applied.
    """
    if isinstance(payload, dict):
        changes = list(payload.get("changes", []))
    elif isinstance(payload, list):
        changes = list(payload)
    else:
        raise ValueError("changes payload must be a JSON object or array")

    original_lines = proof_base_text.splitlines(keepends=True)
    lines_norm = [_nfc(line) for line in original_lines]

    # Phase 1: classify eligibility and resolve a target span for every
    # change, without mutating anything yet.
    resolved: list[dict] = []
    for change in changes:
        entry = {"change": change, "annotated": None, "span": None, "line_idx": None}

        after_norm = _nfc(change.get("after"))
        meaning_risk = change.get("meaningRisk")
        before_norm = _nfc(change.get("before"))

        # Pass through any skip already decided upstream (citation-guard,
        # refuted) untouched.
        must_catch = change.get("mustCatch") is True
        if not must_catch and change.get("applied") is False and change.get("skipReason") in (
            "citation-guard",
            "refuted",
        ):
            entry["annotated"] = dict(change)
            resolved.append(entry)
            continue

        if after_norm is None:
            annotated = dict(change)
            annotated["applied"] = False
            annotated["skipReason"] = "comment-only"
            entry["annotated"] = annotated
            resolved.append(entry)
            continue

        if not must_catch and meaning_risk in ("medium", "high"):
            annotated = dict(change)
            annotated["applied"] = False
            annotated["skipReason"] = "meaning-risk"
            entry["annotated"] = annotated
            resolved.append(entry)
            continue

        line_no = change.get("line")
        if before_norm is None or not isinstance(line_no, int):
            annotated = dict(change)
            annotated["applied"] = False
            annotated["skipReason"] = "no-match"
            entry["annotated"] = annotated
            resolved.append(entry)
            continue

        occurrence = change.get("occurrence")
        if isinstance(occurrence, int) and not isinstance(occurrence, bool) and occurrence >= 1:
            # An upstream finder (must-catch.py's capped-word rule) already knows
            # WHICH instance on this line it means, so skip the ambiguity check
            # entirely and target that instance directly. Falls through to
            # "no-match" (never a guess at another line) when the line doesn't
            # actually have that many occurrences.
            line_idx, span = _resolve_line_by_occurrence(lines_norm, line_no, before_norm, occurrence)
            if line_idx is None or span is None:
                annotated = dict(change)
                annotated["applied"] = False
                annotated["skipReason"] = "no-match"
                entry["annotated"] = annotated
                resolved.append(entry)
                continue
            entry["line_idx"] = line_idx
            entry["span"] = span
            entry["before_norm"] = before_norm
            entry["after_norm"] = after_norm
            resolved.append(entry)
            continue

        try:
            # Preserve the established same-line duplicate diagnostic.
            try:
                _match_on_line(lines_norm, line_no - 1, before_norm)
            except AmbiguousMatch:
                raise AmbiguousMatch()
            candidates = []
            for candidate_line in range(max(1, line_no - 3), min(len(lines_norm), line_no + 3) + 1):
                try:
                    candidate_span = _match_on_line(lines_norm, candidate_line - 1, before_norm)
                except AmbiguousMatch:
                    candidate_span = None
                if candidate_span is not None:
                    candidates.append((abs(candidate_line - line_no), candidate_line - 1, candidate_span))
            if not candidates:
                line_idx, span = None, None
            else:
                candidates.sort(key=lambda item: item[0])
                if len(candidates) > 1 and candidates[0][0] == candidates[1][0]:
                    raise AnchorAmbiguous()
                _, line_idx, span = candidates[0]
        except AmbiguousMatch:
            annotated = dict(change)
            annotated["applied"] = False
            annotated["skipReason"] = "ambiguous-match"
            entry["annotated"] = annotated
            resolved.append(entry)
            continue
        except AnchorAmbiguous:
            annotated = dict(change)
            annotated["applied"] = False
            annotated["skipReason"] = "ambiguous-anchor"
            entry["annotated"] = annotated
            resolved.append(entry)
            continue

        if line_idx is None or span is None:
            annotated = dict(change)
            annotated["applied"] = False
            annotated["skipReason"] = "no-match"
            entry["annotated"] = annotated
            resolved.append(entry)
            continue

        entry["line_idx"] = line_idx
        entry["span"] = span
        entry["before_norm"] = before_norm
        entry["after_norm"] = after_norm
        resolved.append(entry)

    # Phase 2: merge overlapping same-line edits. Group still-pending
    # entries by resolved line, sort by span start, and mark every entry
    # after the first in an overlapping cluster as skipReason="overlap".
    by_line: dict[int, list[int]] = {}
    for i, entry in enumerate(resolved):
        if entry["annotated"] is None and entry["line_idx"] is not None:
            by_line.setdefault(entry["line_idx"], []).append(i)

    for line_idx, indices in by_line.items():
        indices.sort(key=lambda i: resolved[i]["span"][0])
        last_end = None
        for i in indices:
            span = resolved[i]["span"]
            if last_end is not None and span[0] < last_end:
                annotated = dict(resolved[i]["change"])
                annotated["applied"] = False
                annotated["skipReason"] = "overlap"
                resolved[i]["annotated"] = annotated
                resolved[i]["line_idx"] = None
            else:
                last_end = span[1]

    # Phase 3: apply remaining eligible edits bottom-to-top by line so an
    # earlier (lower-index) edit's offsets are never shifted by a later
    # (higher-index) one within the same line. Process lines from the last
    # to the first; within a line, apply right-to-left (highest span start
    # first) for the same reason.
    new_lines = list(original_lines)
    pending_lines = sorted(
        {entry["line_idx"] for entry in resolved if entry["annotated"] is None and entry["line_idx"] is not None},
        reverse=True,
    )
    for line_idx in pending_lines:
        entries_here = [e for e in resolved if e["line_idx"] == line_idx and e["annotated"] is None]
        entries_here.sort(key=lambda e: e["span"][0], reverse=True)

        # Work against the normalized line text so spans (computed on
        # normalized text) line up; write the result back as the new line.
        working = lines_norm[line_idx]
        for entry in entries_here:
            start, end = entry["span"]
            working = working[:start] + entry["after_norm"] + working[end:]
            annotated = dict(entry["change"])
            annotated["applied"] = True
            annotated["skipReason"] = None
            entry["annotated"] = annotated
        new_lines[line_idx] = working

    new_text = "".join(new_lines)

    annotated_changes = [entry["annotated"] for entry in resolved]

    if isinstance(payload, dict):
        result = dict(payload)
        result["changes"] = annotated_changes
        return result, new_text
    return annotated_changes, new_text


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Deterministic change-applier for proofread changes-schema payloads."
    )
    parser.add_argument(
        "--changes",
        required=True,
        help="Path to a JSON file matching changes-schema.json (object or bare array).",
    )
    parser.add_argument(
        "--proof-base",
        required=True,
        help="Path to the PROOF_BASE text file the changes reference (and, "
        "unless --dry-run, the file rewritten in place or via --output).",
    )
    parser.add_argument(
        "--output",
        default=None,
        help="Write the modified text here instead of overwriting --proof-base.",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Report what would happen without writing anything.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Emit JSON output (currently the only supported format).",
    )
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        payload = json.loads(Path(args.changes).read_text(encoding="utf-8"))
        proof_base_text = Path(args.proof_base).read_text(encoding="utf-8")
    except OSError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2
    except json.JSONDecodeError as exc:
        print(json.dumps({"error": f"invalid JSON in --changes: {exc}"}), file=sys.stderr)
        return 2

    try:
        result, new_text = apply_changes(payload, proof_base_text)
    except ValueError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2

    if not args.dry_run:
        out_path = Path(args.output) if args.output else Path(args.proof_base)
        out_path.write_text(new_text, encoding="utf-8")

    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
